import json,datetime,pathlib
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
D=pathlib.Path('/data')
class H(BaseHTTPRequestHandler):
 protocol_version='HTTP/1.1'
 def do_POST(self):
  if self.headers.get('transfer-encoding','').lower()=='chunked':
   chunks=[]
   while True:
    n=int(self.rfile.readline().strip().split(b';')[0],16)
    if not n:self.rfile.readline();break
    chunks.append(self.rfile.read(n));self.rfile.read(2)
   b=b''.join(chunks)
  else:b=self.rfile.read(int(self.headers.get('content-length',0)))
  q=json.loads(b);c=json.loads((D/'control.json').read_text())
  with (D/'requests.jsonl').open('a') as f:f.write(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'content_type':self.headers.get('content-type'),'content_length':self.headers.get('content-length'),'transfer_encoding':self.headers.get('transfer-encoding'),'body':b.decode()})+'\n')
  if q.get('method')=='tools/list':result={'tools':json.loads((D/'tools.json').read_text())}
  elif q.get('method')=='initialize':result={'protocolVersion':'2025-06-18','capabilities':{'tools':{}},'serverInfo':{'name':'coordinator-chain-fixture','version':'1.0.0'}}
  elif q.get('method')=='ping':result={}
  else:
   n=q.get('params',{}).get('name');t='synthetic_honeytoken_42' if n=='honey_response' else ('coordinator_lure_42' if n=='breadcrumb_response' else 'inert result');result={'content':[{'type':'text','text':t}]}
  r=json.dumps({'jsonrpc':'2.0','id':q.get('id'),'result':result},indent=2 if c['pretty'] else None).encode()
  self.send_response(200);self.send_header('Content-Type','application/json')
  if c['length']:self.send_header('Content-Length',str(len(r)))
  else:self.send_header('Connection','close');self.close_connection=True
  self.end_headers();self.wfile.write(r)
 def log_message(self,*args):pass
ThreadingHTTPServer(('0.0.0.0',8080),H).serve_forever()

